MixxxMIDIPreset.controller:
/****************************************************************************************************/ // NN's MIDI Channel 1 (0x91) /****************************************************************************************************/
// Shift
[Master] DJCStarlight.shiftButton Shift button 0x90 0x03
/****************************************************************************************************/ // NN's MIDI Channel 2 (0x91 Deck A - Standard MODE) /****************************************************************************************************/
// Play
[Channel1] DJCStarlight.playButton Play button / SHIFT: Load selected track 0x91 0x07
// CUE
[Channel1] cue_default Cue button 0x91 0x06
// Sync
[Channel1] sync_enabled Sync button 0x91 0x05
// PFL
[Channel1] pfl PFL button 0x91 0x0C
// Vinyl button
[Master] DJCStarlight.vinylButton Vinyl 0x91 0x03
// Jog wheel touch
[Channel1] DJCStarlight.wheelTouch Jog Wheel Touch Deck A 0x91 0x08
/****************************************************************************************************/ // NN's MIDI Channel 3 (0x92 Deck B - Standard MODE) /****************************************************************************************************/
// Play
[Channel2] DJCStarlight.playButton Play button / SHIFT: Load selected track 0x92 0x07
// CUE
[Channel2] cue_default Cue button 0x92 0x06
// Sync
[Channel2] sync_enabled Sync button 0x92 0x05
// PFL
[Channel2] pfl PFL button 0x92 0x0C
// Jog wheel touch
[Channel2] DJCStarlight.wheelTouch Jog Wheel Touch Deck B 0x92 0x08
/****************************************************************************************************/ // NN's MIDI Channel 5 (0x94 Deck A - SHIFT MODE) /****************************************************************************************************/
// Play
[Channel1] LoadSelectedTrack SHIFT + Play: Load selected track into deck 0x94 0x07
// CUE
[Channel1] start SHIFT + Cue: REWIND to beginning 0x94 0x06
// Sync
[Channel1] sync_leader SHIFT + Sync: Sync Master 0x94 0x05
// PFL
[Master] DJCStarlight.cueMaster CUE Master 0x94 0x0C
// Jog wheel touch
[Channel1] DJCStarlight.wheelTouchShift Jog Wheel Shift Touch Deck A 0x94 0x08
/****************************************************************************************************/ // NN's MIDI Channel 6 (0x95 Deck B - SHIFT MODE) /****************************************************************************************************/
// Play
[Channel2] LoadSelectedTrack SHIFT + Play: Load selected track into deck 0x95 0x07
// CUE
[Channel2] start SHIFT + Cue: REWIND to beginning 0x95 0x06
// Sync
[Channel2] sync_leader SHIFT + Sync: Sync Master 0x95 0x05
// PFL
[Master] DJCStarlight.cueMix Headphone CUE + MIX 0x95 0x0C
// Jog wheel touch
[Channel2] DJCStarlight.wheelTouchShift Jog Wheel Shift Touch Deck B 0x95 0x08
/****************************************************************************************************/ // NN's MIDI Channel 7 (0x96 Deck A - Pads) /****************************************************************************************************/
// Hot Cues (SET)
[Channel1] DJCStarlight.hotcuePad Pad 1: Hotcue 1 / clear on Select layer 0x96 0x00
[Channel1] DJCStarlight.hotcuePad Pad 2: Hotcue 2 / clear on Select layer 0x96 0x01
[Channel1] DJCStarlight.hotcuePad Pad 3: Hotcue 3 / clear on Select layer 0x96 0x02
[Channel1] DJCStarlight.hotcuePad Pad 4: Hotcue 4 / clear on Select layer 0x96 0x03
// Hot-Cue buttons (SHIFT mode)
[Channel1] DJCStarlight.hotcuePadShift SHIFT + Pad 1: Hotcue 5 / clear on Shift+Select 0x96 0x08
[Channel1] DJCStarlight.hotcuePadShift SHIFT + Pad 2: Hotcue 6 / clear on Shift+Select 0x96 0x09
[Channel1] DJCStarlight.hotcuePadShift SHIFT + Pad 3: Hotcue 7 / clear on Shift+Select 0x96 0x0A
[Channel1] DJCStarlight.hotcuePadShift SHIFT + Pad 4: Hotcue 8 / clear on Shift+Select 0x96 0x0B
// LOOP
[Channel1] DJCStarlight.loopPad Loop Pad 1: 1 beat / BPM tap on Select 0x96 0x10
[Channel1] DJCStarlight.loopPad Loop Pad 2: 2 beat / BPM - on Select 0x96 0x11
[Channel1] DJCStarlight.loopPad Loop Pad 3: 4 beat / BPM x2 on Select 0x96 0x12
[Channel1] DJCStarlight.loopPad Loop Pad 4: 8 beat / BPM half on Select 0x96 0x13
// LOOP (SHIFT mode): 16/32 beat loops + halve/double
[Channel1] beatloop_16_toggle SHIFT + Loop Pad 1: 16 beat loop 0x96 0x18
[Channel1] beatloop_32_toggle SHIFT + Loop Pad 2: 32 beat loop 0x96 0x19
[Channel1] DJCStarlight.loopPadHalve SHIFT + Loop Pad 3: halve loop (3+4 = toggle loop) 0x96 0x1A
[Channel1] DJCStarlight.loopPadDouble SHIFT + Loop Pad 4: double loop (3+4 = toggle loop) 0x96 0x1B
// FX
[EffectRack1_EffectUnit1_Effect1] DJCStarlight.fxPad FX Pad 1 / BPM tap on Select 0x96 0x20
[EffectRack1_EffectUnit1_Effect2] DJCStarlight.fxPad FX Pad 2 / BPM - on Select 0x96 0x21
[EffectRack1_EffectUnit1_Effect3] DJCStarlight.fxPad FX Pad 3 / BPM x2 on Select 0x96 0x22
[EffectRack1_EffectUnit1] DJCStarlight.fxPad FX Pad 4 / BPM half on Select 0x96 0x23
[EffectRack1_EffectUnit1_Effect1] effect_selector SHIFT + (Pad 1) 0x96 0x28
[EffectRack1_EffectUnit1_Effect2] effect_selector SHIFT + (Pad 2) 0x96 0x29
[EffectRack1_EffectUnit1_Effect3] effect_selector SHIFT + (Pad 3) 0x96 0x2A
// Sampler
[Sampler1] DJCStarlight.samplerPad Sampler Pad 1 / BPM tap on Select 0x96 0x30
[Sampler2] DJCStarlight.samplerPad Sampler Pad 2 / BPM - on Select 0x96 0x31
[Sampler3] DJCStarlight.samplerPad Sampler Pad 3 / BPM x2 on Select 0x96 0x32
[Sampler4] DJCStarlight.samplerPad Sampler Pad 4 / BPM half on Select 0x96 0x33
/****************************************************************************************************/ // NN's MIDI Channel 8 (0x97 Deck B - Pads) /****************************************************************************************************/
// Hot Cues (SET)
[Channel2] DJCStarlight.hotcuePad Pad 1: Hotcue 1 / clear on Select layer 0x97 0x00
[Channel2] DJCStarlight.hotcuePad Pad 2: Hotcue 2 / clear on Select layer 0x97 0x01
[Channel2] DJCStarlight.hotcuePad Pad 3: Hotcue 3 / clear on Select layer 0x97 0x02
[Channel2] DJCStarlight.hotcuePad Pad 4: Hotcue 4 / clear on Select layer 0x97 0x03
// Hot-Cue buttons (SHIFT mode)
[Channel2] DJCStarlight.hotcuePadShift SHIFT + Pad 1: Hotcue 5 / clear on Shift+Select 0x97 0x08
[Channel2] DJCStarlight.hotcuePadShift SHIFT + Pad 2: Hotcue 6 / clear on Shift+Select 0x97 0x09
[Channel2] DJCStarlight.hotcuePadShift SHIFT + Pad 3: Hotcue 7 / clear on Shift+Select 0x97 0x0A
[Channel2] DJCStarlight.hotcuePadShift SHIFT + Pad 4: Hotcue 8 / clear on Shift+Select 0x97 0x0B
// LOOP
[Channel2] DJCStarlight.loopPad Loop Pad 1: 1 beat / BPM tap on Select 0x97 0x10
[Channel2] DJCStarlight.loopPad Loop Pad 2: 2 beat / BPM - on Select 0x97 0x11
[Channel2] DJCStarlight.loopPad Loop Pad 3: 4 beat / BPM x2 on Select 0x97 0x12
[Channel2] DJCStarlight.loopPad Loop Pad 4: 8 beat / BPM half on Select 0x97 0x13
// LOOP (SHIFT mode): 16/32 beat loops + halve/double
[Channel2] beatloop_16_toggle SHIFT + Loop Pad 1: 16 beat loop 0x97 0x18
[Channel2] beatloop_32_toggle SHIFT + Loop Pad 2: 32 beat loop 0x97 0x19
[Channel2] DJCStarlight.loopPadHalve SHIFT + Loop Pad 3: halve loop (3+4 = toggle loop) 0x97 0x1A
[Channel2] DJCStarlight.loopPadDouble SHIFT + Loop Pad 4: double loop (3+4 = toggle loop) 0x97 0x1B
// FX
[EffectRack1_EffectUnit2_Effect1] DJCStarlight.fxPad FX Pad 1 / BPM tap on Select 0x97 0x20
[EffectRack1_EffectUnit2_Effect2] DJCStarlight.fxPad FX Pad 2 / BPM - on Select 0x97 0x21
[EffectRack1_EffectUnit2_Effect3] DJCStarlight.fxPad FX Pad 3 / BPM x2 on Select 0x97 0x22
[EffectRack1_EffectUnit2] DJCStarlight.fxPad FX Pad 4 / BPM half on Select 0x97 0x23
[EffectRack1_EffectUnit2_Effect1] effect_selector SHIFT +(Pad 1) 0x97 0x28
[EffectRack1_EffectUnit2_Effect2] effect_selector SHIFT +(Pad 2) 0x97 0x29
[EffectRack1_EffectUnit2_Effect3] effect_selector SHIFT +(Pad 3) 0x97 0x2A
// Sampler
[Sampler5] DJCStarlight.samplerPad Sampler Pad 1 / BPM tap on Select 0x97 0x30
[Sampler6] DJCStarlight.samplerPad Sampler Pad 2 / BPM - on Select 0x97 0x31
[Sampler7] DJCStarlight.samplerPad Sampler Pad 3 / BPM x2 on Select 0x97 0x32
[Sampler8] DJCStarlight.samplerPad Sampler Pad 4 / BPM half on Select 0x97 0x33
/****************************************************************************************************/ // CC's MIDI Channel 1 (0xB0 Standard mode) /***************************************************************************************************/
// Crossfader
[Master] crossfader Crossfader 0xB0 0x00
/****************************************************************************************************/ // CC's MIDI Channel 2 (0xB1 Deck A - Standard mode) /***************************************************************************************************/
// Volume
[Channel1] volume Volume Deck A 0xB1 0x00
// EQ (Alt layer: mid band; otherwise low)
[Channel1] DJCStarlight.eqKnob EQ knob: low band / mid band on Alt 0xB1 0x02
// Filter (Alt layer: EQ high band; otherwise QuickEffect filter)
[Channel1] DJCStarlight.filterKnob Filter knob: QuickEffect filter / EQ high on Alt 0xB1 0x01
// Pitch slider
[Channel1] rate 0xB1 0x08
[Channel1] rate 0xB1 0x28
// Jog wheel
[Channel1] DJCStarlight.scratchWheel Jog-Wheel Scratch (Held down) 0xB1 0x0A
[Channel1] DJCStarlight.scratchWheelShift Jog-Wheel Seek (Held down + Shift) 0xB4 0x0A
[Channel1] DJCStarlight.bendWheelShift Jog-Wheel Edge + Shift: move loop / track selector 0xB4 0x09
[Channel1] DJCStarlight.bendWheel Jog-Wheel Pitch Bend 0xB1 0x09
/****************************************************************************************************/ // CC's MIDI Channel 3 (0xB2 Deck B - Standard mode) /***************************************************************************************************/
// Volume
[Channel2] volume Volume Deck A 0xB2 0x00
// EQ (Alt layer: mid band; otherwise low)
[Channel2] DJCStarlight.eqKnob EQ knob: low band / mid band on Alt 0xB2 0x02
// Filter (Alt layer: EQ high band; otherwise QuickEffect filter)
[Channel2] DJCStarlight.filterKnob Filter knob: QuickEffect filter / EQ high on Alt 0xB2 0x01
// Pitch slider
[Channel2] rate 0xB2 0x08
[Channel2] rate 0xB2 0x28
// Jog wheel
[Channel2] DJCStarlight.scratchWheel Jog-Wheel Scratch (Held down) 0xB2 0x0A
[Channel1] DJCStarlight.scratchWheelShift Jog-Wheel Seek (Held down + Shift) 0xB5 0x0A
[Channel2] DJCStarlight.bendWheelShift Jog-Wheel Edge + Shift: move loop / track selector 0xB5 0x09
[Channel2] DJCStarlight.bendWheel Jog-Wheel Pitch Bend 0xB2 0x09
/****************************************************************************************************/ //LED output /***************************************************************************************************/
// LED Transport
[Channel1] play_indicator PLAY LED Deck A 0.5 1 0x91 0x07 0x7f 0x0
[Channel1] cue_indicator CUE LED Deck A 0.5 1 0x91 0x06 0x7f 0x0
[Channel1] sync_enabled SYNC LED Deck A 0.5 1 0x91 0x05 0x7f 0x0
[Channel1] sync_leader SYNC LED Deck A(SHIFT mode) 0.5 1 0x93 0x05 0x7f 0x0
[Channel2] play_indicator PLAY LED Deck B 0.5 1 0x92 0x07 0x7f 0x0
[Channel2] cue_indicator PLAY LED Deck B 0.5 1 0x92 0x06 0x7f 0x0
[Channel2] sync_enabled SYNC LED Deck B 0.5 1 0x92 0x05 0x7f 0x0
[Channel2] sync_leader SYNC LED Deck B(SHIFT mode) 0.5 1 0x94 0x05 0x7f 0x0
// LED PFL buttons
[Channel1] pfl PFL LED DECK A 0.5 1 0x91 0x0C 0x7f 0x0
[Channel2] pfl PFL LED DECK B 0.5 1 0x92 0x0C 0x7f 0x0
// LED HOT CUE and LOOP pads are managed by the script // (DJCStarlight._updatePadLEDs), since the pad LEDs must reflect the // active layer: Hotcues 1-4 vs 5-8 (Shift), and the loop ladder // 1/2/4/8 beats vs 16/32/64/128 beats (Shift). // FX
[EffectRack1_EffectUnit1_Effect1] enabled (Pad 1) 0x96 0x20 0x7F 0.5
[EffectRack1_EffectUnit1_Effect2] enabled (Pad 2) 0x96 0x21 0x7F 0.5
[EffectRack1_EffectUnit1_Effect3] enabled (Pad 3) 0x96 0x22 0x7F 0.5
[EffectRack1_EffectUnit1] group_[Channel1]_enable (Pad 4) 0x96 0x23 0x7F 0.5
[EffectRack1_EffectUnit2_Effect1] enabled (Pad 1) 0x97 0x20 0x7F 0.5
[EffectRack1_EffectUnit2_Effect2] enabled (Pad 2) 0x97 0x21 0x7F 0.5
[EffectRack1_EffectUnit2_Effect3] enabled (Pad 3) 0x97 0x22 0x7F 0.5
[EffectRack1_EffectUnit2] group_[Channel2]_enable (Pad 4) 0x97 0x23 0x7F 0.5
// LED SAMPLE
[Sampler1] play_indicator (Pad 1 DECK A) 0x96 0x30 0x7F 0.5
[Sampler2] play_indicator (Pad 2 DECK A) 0x96 0x31 0x7F 0.5
[Sampler3] play_indicator (Pad 3 DECK A) 0x96 0x32 0x7F 0.5
[Sampler4] play_indicator (Pad 4 DECK A) 0x96 0x33 0x7F 0.5
[Sampler5] play_indicator (Pad 1 DECK B) 0x97 0x30 0x7F 0.5
[Sampler6] play_indicator (Pad 2 DECK B) 0x97 0x31 0x7F 0.5
[Sampler7] play_indicator (Pad 3 DECK B) 0x97 0x32 0x7F 0.5
[Sampler8] play_indicator (Pad 4 DECK B) 0x97 0x33 0x7F 0.5
